/* A housekeeping helper for list elements popping tasks.
 *
 * 'deleted' is an optional output argument to get an indication
 * if the key got deleted by this function. */
void listElementsRemoved(client *c, robj *key, int where, robj *o, long count, int *deleted) {
    char *event = (where == LIST_HEAD) ? "lpop" : "rpop";

    notifyKeyspaceEvent(NOTIFY_LIST, event, key, c->db->id);
    if (listTypeLength(o) == 0) {
        if (deleted) *deleted = 1;

        dbDelete(c->db, key);
        notifyKeyspaceEvent(NOTIFY_GENERIC, "del", key, c->db->id);
    } else {
        if (deleted) *deleted = 0;
    }
    signalModifiedKey(c, c->db, key);
    server.dirty += count;
}

/* Implements the generic list pop operation for LPOP/RPOP.
 * The where argument specifies which end of the list is operated on. An
 * optional count may be provided as the third argument of the client's
 * command. */
void popGenericCommand(client *c, int where) {
    int hascount = (c->argc == 3);
    long count = 0;
    robj *value = NULL;
    robj *key = c->argv[1];
    robj *countobj;
    robj *o;
    long long parsed = 0;
    int parse_ok = 1;
    long long vlong = 0;
    int ql_where;
    unsigned long llen = 0;
    long rangelen;
    long rangestart;
    long rangeend;
    int reverse;
    long start;
    long end;
    long replylen;
    long from;
    unsigned char direction;
    int iter_direction;
    listTypeIterator *li;
    listTypeEntry entry;
    quicklistEntry *qe;

    if (c->argc > 3) {
        addReplyErrorFormat(c,"wrong number of arguments for '%s' command",
                            c->cmd->name);
        return;
    } else if (hascount) {
        countobj = c->argv[2];
        serverAssertWithInfo(NULL, countobj, countobj->type == OBJ_STRING);
        if (countobj->encoding == OBJ_ENCODING_RAW ||
            countobj->encoding == OBJ_ENCODING_EMBSTR) {
            if (string2ll(countobj->ptr, sdslen(countobj->ptr), &parsed) == 0) {
                parse_ok = 0;
            }
        } else if (countobj->encoding == OBJ_ENCODING_INT) {
            parsed = (long) countobj->ptr;
        } else {
            serverPanic("Unknown string encoding");
        }
        if (!parse_ok) {
            addReplyError(c, "value is out of range, must be positive");
            return;
        }
        if (parsed < 0) {
            addReplyError(c, "value is out of range, must be positive");
            return;
        }
        if (parsed > LONG_MAX) {
            addReplyError(c, "value is out of range, must be positive");
            return;
        }
        count = (long) parsed;
    }

    o = lookupKeyWrite(c->db, key);
    if (o == NULL) {
        addReplyOrErrorObject(c, shared.null[c->resp]);
        return;
    }
    if (o->type != OBJ_LIST) {
        addReplyErrorObject(c, shared.wrongtypeerr);
        return;
    }

    if (hascount) {
        if (count == 0) {
            addReply(c, shared.emptyarray);
            return;
        }
    }

    if (count == 0) {
        value = NULL;
        vlong = 0;
        if (where == LIST_HEAD) {
            ql_where = QUICKLIST_HEAD;
        } else {
            ql_where = QUICKLIST_TAIL;
        }
        if (o->encoding == OBJ_ENCODING_QUICKLIST) {
            if (quicklistPopCustom(o->ptr, ql_where, (unsigned char **)&value,
                                   NULL, &vlong, listPopSaver)) {
                if (value == NULL) {
                    value = createStringObjectFromLongLong(vlong);
                }
            }
        } else {
            serverPanic("Unknown list encoding");
        }
        serverAssert(value != NULL);
        addReplyBulk(c, value);
        decrRefCount(value);
        listElementsRemoved(c, key, where, o, 1, NULL);
    } else {
        if (o->encoding == OBJ_ENCODING_QUICKLIST) {
            llen = quicklistCount(o->ptr);
        } else {
            serverPanic("Unknown list encoding");
        }

        if (count > (long) llen) {
            rangelen = (long) llen;
        } else {
            rangelen = count;
        }

        if (where == LIST_HEAD) {
            rangestart = 0;
            rangeend = rangelen - 1;
            reverse = 0;
        } else {
            rangestart = -rangelen;
            rangeend = -1;
            reverse = 1;
        }

        start = rangestart;
        end = rangeend;
        if (start < 0) {
            start = (long) llen + start;
        }
        if (end < 0) {
            end = (long) llen + end;
        }
        if (start < 0) {
            start = 0;
        }

        if (start > end || start >= (long) llen) {
            addReply(c, shared.emptyarray);
        } else {
            if (end >= (long) llen) {
                end = (long) llen - 1;
            }
            replylen = (end - start) + 1;
            addReplyArrayLen(c, replylen);
            if (o->encoding == OBJ_ENCODING_QUICKLIST) {
                if (reverse) {
                    from = end;
                    direction = LIST_HEAD;
                } else {
                    from = start;
                    direction = LIST_TAIL;
                }
                if (direction == LIST_HEAD) {
                    iter_direction = AL_START_TAIL;
                } else {
                    iter_direction = AL_START_HEAD;
                }

                li = zmalloc(sizeof(listTypeIterator));
                li->subject = o;
                li->encoding = o->encoding;
                li->direction = direction;
                li->iter = NULL;
                li->iter = quicklistGetIteratorAtIdx(li->subject->ptr,
                                                     iter_direction, from);

                while (replylen--) {
                    entry.li = li;
                    serverAssert(li->subject->encoding == li->encoding);
                    if (li->encoding == OBJ_ENCODING_QUICKLIST) {
                        serverAssert(quicklistNext(li->iter, &entry.entry));
                        qe = &entry.entry;
                        if (qe->value) {
                            addReplyBulkCBuffer(c, qe->value, qe->sz);
                        } else {
                            addReplyBulkLongLong(c, qe->longval);
                        }
                    } else {
                        serverPanic("Unknown list encoding");
                    }
                }
                quicklistReleaseIterator(li->iter);
                zfree(li);
            } else {
                serverPanic("Unknown list encoding");
            }
        }

        if (o->encoding == OBJ_ENCODING_QUICKLIST) {
            quicklistDelRange(o->ptr, rangestart, rangelen);
        } else {
            serverPanic("Unknown list encoding");
        }
        listElementsRemoved(c, key, where, o, rangelen, NULL);
    }
}

